using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ResolveDesk.Data;
using ResolveDesk.Models;
using ResolveDesk.Services;
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("DefaultConnection")));
builder.Services.AddDefaultIdentity<ApplicationUser>(o=>{o.SignIn.RequireConfirmedAccount=false;o.Password.RequiredLength=8;o.Lockout.MaxFailedAccessAttempts=5;}).AddRoles<IdentityRole>().AddEntityFrameworkStores<ApplicationDbContext>();
builder.Services.ConfigureApplicationCookie(o=>{o.LoginPath="/Identity/Account/Login";o.AccessDeniedPath="/Home/AccessDenied";o.Cookie.HttpOnly=true;o.Cookie.SameSite=SameSiteMode.Lax;});
builder.Services.AddAuthorization(o=>o.AddPolicy("Staff",p=>p.RequireRole("Agent","DepartmentAdmin","SuperAdmin")));
builder.Services.AddControllersWithViews(); builder.Services.AddRazorPages(); builder.Services.AddScoped<ITicketWorkflowService,TicketWorkflowService>();
var app=builder.Build(); if(!app.Environment.IsDevelopment()){app.UseExceptionHandler("/Home/Error");app.UseHsts();} app.UseHttpsRedirection();app.UseStaticFiles();app.UseRouting();app.UseAuthentication();app.UseAuthorization();app.MapControllerRoute(name:"default",pattern:"{controller=Home}/{action=Index}/{id?}");app.MapRazorPages();app.MapGet("/health",()=>Results.Ok(new{status="healthy"})); using(var s=app.Services.CreateScope())await SeedData.InitializeAsync(s.ServiceProvider); app.Run();
